/* PATCH v1.1.1 UPDATER MODAL */
.updater-modal-layout {
    display: flex !important;
    flex-direction: column !important;
    max-height: 85vh !important;
    padding: 0 !important;
    overflow: hidden !important;
    width: 100%;
    max-width: 560px;
    background: var(--pg-card-bg);
    border: 1px solid var(--pg-card-border);
    border-radius: 18px;
    box-shadow: 0 20px 60px rgba(0,0,0,0.55);
}
.updater-modal-header {
    padding: 20px 24px 16px !important;
    border-bottom: 1px solid rgba(128,128,128,0.2) !important;
    flex: 0 0 auto !important;
}
.updater-modal-scroll {
    flex: 1 1 auto !important;
    overflow-y: auto !important;
    padding: 20px 24px !important;
    min-height: 0 !important;
}
.updater-modal-scroll::-webkit-scrollbar { width: 8px; }
.updater-modal-scroll::-webkit-scrollbar-track { background: rgba(128,128,128,0.05); border-radius: 4px; }
.updater-modal-scroll::-webkit-scrollbar-thumb { background: var(--trk-card-border, rgba(128,128,128,0.2)); border-radius: 4px; }
.updater-modal-scroll::-webkit-scrollbar-thumb:hover { background: var(--trk-accent, #f5d76e); }
.updater-modal-footer {
    padding: 16px 24px 20px !important;
    border-top: 1px solid rgba(128,128,128,0.2) !important;
    background: var(--pg-card-bg) !important;
    flex: 0 0 auto !important;
}
</style>
